from pathlib import Path
path = Path('src/components/TimelineIssueCard.jsx')
text = path.read_text()
old = "      {ISSUE_STATE_TOGGLES.map(({ key, label, Icon }) => {\n        const active = Boolean(issueState?.[key])\n        const isDisabled = disabled || pending\n        return (\n          <button\n            key={key}\n            type=\"button\"\n            aria-pressed={active}\n            disabled={isDisabled}\n            onClick={() => onToggle?.(key, !active)}\n            title={isDisabled ? disabledReason ?? 'Issue states unavailable' : undefined}\n            className={`inline-flex items-center gap-2 rounded-full border px-3 py-1 text-xs font-semibold transition focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-slate-400 ${\n              active\n                ? 'border-slate-900 bg-slate-900 text-white shadow'\n                : 'border-slate-200 bg-white text-slate-600 hover:border-slate-900/40 hover:text-slate-900'\n            } ${isDisabled ? 'cursor-not-allowed opacity-60' : ''}`}\n          >\n            <Icon className=\"h-3.5 w-3.5\" aria-hidden=\"true\" />\n            {label}\n          </button>\n        )\n      })}\n"
new = "      {ISSUE_STATE_TOGGLES.map(({ key, label, Icon, activeClasses }) => {\n        const active = Boolean(issueState?.[key])\n        const isDisabled = disabled || pending\n        const baseButtonClasses = 'inline-flex items-center gap-2 rounded-full border px-3 py-1 text-xs font-semibold transition focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-slate-400'\n        const filledClasses = activeClasses ?? 'border-slate-900 bg-slate-900 text-white shadow'\n        return (\n          <button\n            key={key}\n            type=\"button\"\n            aria-pressed={active}\n            disabled={isDisabled}\n            onClick={() => onToggle?.(key, !active)}\n            title={isDisabled ? disabledReason ?? 'Issue states unavailable' : undefined}\n            className={`${baseButtonClasses} ${\n              active\n                ? filledClasses\n                : 'border-slate-200 bg-white text-slate-600 hover:border-slate-900/40 hover:text-slate-900'\n            } ${isDisabled ? 'cursor-not-allowed opacity-60' : ''}`}\n          >\n            <Icon className=\"h-3.5 w-3.5\" aria-hidden=\"true\" />\n            {label}\n          </button>\n        )\n      })}\n"
if old not in text:
    raise SystemExit('button block not found')
path.write_text(text.replace(old, new, 1))
